WITH RECURSIVE numbers(n) AS (
  SELECT 1               -- anchor: start at 1
  UNION ALL
  SELECT n + 1           -- recursive: add 1 each iteration
  FROM numbers
  WHERE n < 20           -- termination: stop at 20
)
SELECT n FROM numbers;

-- Anchor: returns {1}
-- Iteration 2: 1+1 = {2}
-- Iteration 3: 2+1 = {3}
-- ...
-- Iteration 20: 19+1 = {20}
-- Iteration 21: WHERE 20 < 20 is false, recursion stops
